package main

import (
    "encoding/json"
    "fmt"
    "log"
    "time"

    "github.com/pilot-protocol/common/driver"
    "github.com/pilot-protocol/common/protocol"
    "github.com/pilot-protocol/eventstream"
)

type Message struct {
    Type    string          `json:"type"`
    Payload json.RawMessage `json:"payload"`
    Ts      int64           `json:"ts"`
}

// Both agents use the event stream (port 1002) of a node they both trust
func coordinator(d *driver.Driver) protocol.Addr {
    res, err := d.ResolveHostname("coordinator")
    if err != nil {
        log.Fatal(err)
    }
    addr, err := protocol.ParseAddr(res["address"].(string))
    if err != nil {
        log.Fatal(err)
    }
    return addr
}

// Agent A: sends tasks and receives results
func runAgentA() {
    d, _ := driver.Connect("")

    // Subscribe to results from Agent B
    stream, err := eventstream.Subscribe(d, coordinator(d), "agent-b.results")
    if err != nil {
        log.Fatal(err)
    }

    // Handle incoming results in background
    go func() {
        for {
            event, err := stream.Recv()
            if err != nil {
                return
            }
            var msg Message
            json.Unmarshal(event.Payload, &msg)
            fmt.Printf("[A] Received result: %s\n", string(msg.Payload))
        }
    }()

    // Send tasks periodically on the same connection
    for i := 0; ; i++ {
        task := Message{
            Type:    "task",
            Payload: json.RawMessage(fmt.Sprintf(`{"id":%d,"work":"analyze dataset %d"}`, i, i)),
            Ts:      time.Now().Unix(),
        }
        data, _ := json.Marshal(task)
        stream.Publish("agent-a.tasks", data)
        fmt.Printf("[A] Sent task %d\n", i)
        time.Sleep(10 * time.Second)
    }
}

// Agent B: receives tasks and sends results
func runAgentB() {
    d, _ := driver.Connect("")

    // Subscribe to tasks from Agent A
    stream, err := eventstream.Subscribe(d, coordinator(d), "agent-a.tasks")
    if err != nil {
        log.Fatal(err)
    }

    for {
        event, err := stream.Recv()
        if err != nil {
            return
        }
        var msg Message
        json.Unmarshal(event.Payload, &msg)
        fmt.Printf("[B] Received task: %s\n", string(msg.Payload))

        // Process the task
        time.Sleep(2 * time.Second) // Simulate work

        // Send result back (B initiates, not responding to a request)
        result := Message{
            Type:    "result",
            Payload: json.RawMessage(`{"status":"complete","confidence":0.95}`),
            Ts:      time.Now().Unix(),
        }
        data, _ := json.Marshal(result)
        stream.Publish("agent-b.results", data)
        fmt.Printf("[B] Sent result\n")
    }
}
